import java.util.*;
import java.io.*;

public class Main {
    static final int DEPTH_LIMIT = 7;
    static final int MAX_BASE = 1000000;
    static final long MOD_A = 998244353L;
    static final long MOD_B = 1000000007L;
    static long total_input_value;
    static long total_counter;
    static List<Integer>[] digit_collections = new ArrayList[DEPTH_LIMIT];
    static int final_result = 0;
    static long[] prefix_sums = new long[DEPTH_LIMIT];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        total_input_value = Long.parseLong(br.readLine().trim());

        for (int i = 0; i < DEPTH_LIMIT; i++) {
            digit_collections[i] = new ArrayList<>();
        }

        generate_numbers(0, 0);

        for (int d = 0; d <= 6; d++) {
            Collections.sort(digit_collections[d]);
            for (int v : digit_collections[d]) {
                prefix_sums[d] = (prefix_sums[d] + v) % MOD_B;
            }
        }

        total_counter = 0;
        process_node(0, 0L);

        System.out.println(final_result);
    }

    static void generate_numbers(int level, long val) {
        total_counter++;
        digit_collections[level].add((int)((total_counter - val + MOD_A) % MOD_A));
        if (level == 6) return;
        for (int digit = 0; digit < 10; digit++) {
            generate_numbers(level + 1, val * 10 + digit);
        }
    }

    static void process_node(int depth, long v) {
        if (v > total_input_value) return;
        if (depth != 0) {
            if (v * MAX_BASE > total_input_value / 10 && (v + 1) * MAX_BASE - 1 <= total_input_value) {
                for (int i = 0, pwr = 1; i <= 6; i++, pwr *= 10) {
                    long coef = (total_counter - (v * pwr) % MOD_A + MOD_A) % MOD_A;
                    List<Integer> list = digit_collections[i];
                    int idx = lowerBound(list, (int)(MOD_A - coef));
                    long size = list.size();
                    long sum = prefix_sums[i];
                    long count = size - idx;
                    final_result = (int)((final_result + coef * size + sum - MOD_A * count % MOD_B + MOD_B) % MOD_B);
                }
                for (int i = 0; i <= 6; i++) {
                    total_counter += digit_collections[i].size();
                }
                return;
            }
            final_result = (int)((final_result + (++total_counter - v % MOD_A + MOD_A) % MOD_A) % MOD_B);
        }
        for (int c = (depth == 0 ? 1 : 0); c < 10; c++) {
            process_node(depth + 1, v * 10 + c);
        }
    }

    static int lowerBound(List<Integer> list, int target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= target) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}
